"""Readable chart guide, with the technical definitions kept one click away."""
from html import escape
from pathlib import Path
from .branding import branding, with_hero_flag
from .site_navigation import with_navigation


def bilingual(tag,nl,en,attrs=''):
    return f'<{tag}{attrs} data-nl="{escape(nl,quote=True)}" data-en="{escape(en,quote=True)}">{escape(nl)}</{tag}>'


def render():
    p=lambda a,b:bilingual('p',a,b)
    h=lambda a,b:bilingual('h2',a,b)
    sections=[]
    def section(id,nl,en,body):sections.append('<section class="help-card" id="'+id+'">'+h(nl,en)+body+'</section>')
    section('lezen','Zo lees je de grafieken','How to read the charts',
        p('Begin met de vraag boven de grafiek. Bekijk daarna wat één punt betekent: soms één race, soms één ronde en soms één rijder. Kijk ook hoeveel gegevens beschikbaar zijn. Geen punt betekent ontbrekende informatie, niet nul.','Start with the question above the chart. Then check what one dot means: sometimes one race, sometimes one lap and sometimes one driver. Also check how much data is available. No dot means missing information, not zero.')+
        p('Een gekleurde vorm laat zien waar veel resultaten samenkomen: breder betekent dat daar meer meetwaarden liggen. De witte streep markeert de middelste waarde. Het dikke gekleurde lijntje bevat de middelste helft van de resultaten. Dat is spreiding, geen onzekerheidsmarge.','A coloured shape shows where results gather: wider means more measurements are there. The white bar marks the middle value. The thick coloured line contains the middle half of the results. That is spread, not an uncertainty interval.')+
        p('De vloeiende lijn vat het verloop samen. De grijze of gekleurde band daaromheen laat zien hoe onzeker die lijn is. Een stip is een meting; de lijn is een berekende samenvatting.','The smooth line summarizes the pattern. The grey or coloured band around it shows uncertainty in that line. A dot is a measurement; the line is a calculated summary.'))
    section('midden','Middelste waarde is niet hetzelfde als gemiddelde','The middle value is not the mean',
        p('We gebruiken vaak de middelste waarde, ook mediaan genoemd. Sorteer de uitkomsten van laag naar hoog en neem de middelste. Bij een even aantal neem je het gemiddelde van de twee middelste. Eén extreme race heeft zo minder invloed dan bij een gewoon gemiddelde.','We often use the middle value, also called the median. Sort the results from low to high and take the middle one. With an even number, average the two middle values. One extreme race then has less influence than with an ordinary mean.')+
        p('Voorbeeld: 1, 2, 3 en 20 seconden hebben als middelste waarde 2,5 seconden. Het gewone gemiddelde is 6,5 seconden. Met “typische tijdwinst” bedoelen we hier die middelste waarde. Staat er “gemiddeld”, dan gebruiken we wel het gewone gemiddelde.','Example: 1, 2, 3 and 20 seconds have a middle value of 2.5 seconds. Their ordinary mean is 6.5 seconds. “Typical time gained” means the middle value here. If a label says “mean”, it does use the ordinary mean.'))
    section('onzekerheid','Wat zegt de onzekerheidsmarge?','What does the uncertainty range tell you?',
        p('Met weinig races kan één uitslag het beeld sterk veranderen. Een brede marge laat zien dat de samenvatting minder precies is. Kleine verschillen of overlappende marges zijn geen reden om één rijder zonder meer beter te noemen.','With few races, one result can change the picture substantially. A wide range shows that the summary is less precise. Small differences or overlapping ranges do not justify declaring one driver better.')+
        p('Een marge van 95% rond een lijn zegt niet dat 95% van de races in die band hoort te liggen. Zij gaat over de onzekerheid van de berekende lijn. Ook neemt die marge niet vanzelf verschillen in auto, weer of meetkwaliteit weg.','A 95% range around a line does not mean 95% of races should lie inside it. It describes uncertainty in the calculated line. It also does not automatically remove car, weather or measurement-quality differences.')+
        '<details>'+bilingual('summary','Technisch: lijn en onzekerheid','Technical: curve and uncertainty')+
        p('Kwalificatie- en pitseizoenscurves gebruiken een robuust Gaussisch venster over de chronologische races (sigma vijf races), gevolgd door verzachting over 0,3 seizoen. De 95%-band gebruikt 400 moving-block-bootstrapherhalingen met blokken van drie races. Dit houdt gedeeltelijk rekening met samenhang tussen opeenvolgende races.','Qualifying and pit-season curves use a robust Gaussian window over chronological races (sigma five races), followed by smoothing over 0.3 seasons. The 95% band uses 400 moving-block bootstrap replicates with blocks of three races. This partly accounts for dependence between consecutive races.')+
        p('Start- en racevervolgcurves gebruiken een ander model. Hun modelband is geen band van losse race-uitkomsten. De exacte definitie, ondersteuning en eventuele terugvalmethode staan bij Start en raceonderzoek. Schatfout van vertaalde kwalificatietijden zit niet volledig in de kwalificatieband.','Start and race-progression curves use a different model. Their model band is not a band of individual race outcomes. Exact definitions, support and fallback methods are in Start and race research. Translation error in estimated qualifying times is not fully included in the qualifying band.')+'</details>')
    section('assen','Waarom zijn sommige assen niet gelijk verdeeld?','Why are some axes unevenly spaced?',
        p('Kleine verschillen zijn vaak interessant, maar grote uitschieters moeten ook zichtbaar blijven. Daarom geven sommige assen kleine verschillen meer ruimte. Lees de waarden bij de as: de getallen blijven echte plaatsen of seconden. De puntwaarden veranderen niet.','Small differences are often interesting, but large outliers must remain visible too. Some axes therefore give small differences more space. Read the axis labels: the numbers remain actual places or seconds. Point values do not change.')+
        p('Bij de pitbalans blijft nul in het midden. Een seconde winst en een seconde verlies liggen even ver van nul. Bij afstand tot pole staat nul bovenaan en loopt de as tot vier seconden. Een pijltje aan de rand wijst op een waarde buiten de getoonde grens.','Pit balance keeps zero central. One second gained and one second lost are equally far from zero. Gap to pole puts zero at the top and runs to four seconds. An arrow at an edge marks a value beyond the displayed limit.')+
        '<details>'+bilingual('summary','Technisch: de schalen','Technical: the scales')+
        p('Pitbalans gebruikt sign(t) × ln(1 + |t|), met t in seconden. Tijdwinst en verlies zijn symmetrisch. Afstand tot pole gebruikt ln(1 + t) en begrenst de weergave op 0–4 seconden. Start- en vervolgposities gebruiken de vaste ankers 0, 1, 3, 6 en 10 aan beide kanten van nul. De oorspronkelijke waarden blijven bewaard.','Pit balance uses sign(t) × ln(1 + |t|), with t in seconds. Gains and losses are symmetric. Gap to pole uses ln(1 + t), with display limited to 0–4 seconds. Start and progression changes use fixed anchors 0, 1, 3, 6 and 10 on both sides of zero. Original values are retained.')+'</details>')
    section('coureurs','Wat meten de coureurskaarten?','What do the driver cards measure?',
        p('Kwalificaties: de kwalificatie-uitslag en het tijdsverschil met pole. Dat is niet altijd de startplek na straffen. Starts: plaatsen gewonnen of verloren tot het einde van ronde één. Racevervolg: van de positie na ronde één tot de finish, alleen voor rijders die rijdend finishten. Positiewinst is niet hetzelfde als het aantal inhaalacties.','Qualifying: the qualifying result and gap to pole. This is not always the grid after penalties. Starts: places gained or lost by the end of lap one. Race progression: from the lap-one position to the finish, for drivers who were running at the finish only. Places gained is not the same as overtakes made.')+
        p('Vrije baan vergelijkt tempo met de teamgenoot bij passende ronden en banden. De metronoom zet rondetijden naast het veld; P3 betekent hier de derde rondetijd, niet de derde racepositie. Regelmaat kijkt apart naar hoe gelijkmatig het eigen tempo was.','Clear-air pace compares teammates on suitable laps and tyres. The metronome ranks lap times within the field; P3 here means the third lap time, not third race position. Consistency separately examines how steadily a driver repeated their own pace.')+
        p('Bandenbehoud vergelijkt de verandering in tempovoordeel terwijl banden ouder worden. Opwarming vergelijkt vroege ronden op nieuwe banden met het eigen verwachte tempo. Het zijn geen rechtstreekse metingen van slijtage of bandentemperatuur.','Tyre management compares the change in pace advantage as tyres age. Warm-up compares early laps on new tyres with expected own pace. These are not direct measurements of wear or tyre temperature.')+
        p('De pitbalans meet hoeveel het tijdsverschil met een tegenstander veranderde rond hun stops. Eerst 6 seconden achter en daarna 2 seconden achter betekent 4 seconden gewonnen, zonder een plaats te winnen. Tempo en verkeer kunnen daaraan bijdragen.','Pit balance measures how the gap to an opponent changed around their stops. Being 6 seconds behind before and 2 seconds behind afterwards means 4 seconds gained without gaining a place. Pace and traffic can contribute.')+
        '<a href="uitleg-start-en-raceonderzoek.html" data-nl="Alle berekeningen en echte coureursvoorbeelden →" data-en="All calculations and real driver examples →">Alle berekeningen en echte coureursvoorbeelden →</a>')
    section('goat','Rijders vergelijken: eerst de omstandigheden','Comparing drivers: start with the circumstances',
        p('De vaste loopbaancijfers gebruiken alle beschikbare eigen races. Een andere rijder selecteren verandert die cijfers niet. De extra vergelijking kan alleen gezamenlijke races gebruiken, of vergelijkbare situaties met dezelfde beginpositie, circuitvariant en veldgrootte. De resterende invloed van auto, weer en tegenstanders verdwijnt daardoor niet.','Fixed career figures use all available races for that driver. Selecting another driver does not change them. The additional comparison can use shared races or matched situations with the same origin position, layout and field size. This does not remove all remaining car, weather and opponent effects.')+
        p('Bij de vergelijkingsscores betekent 50 ongeveer gelijk aan passende andere rijders. De metronoomveldscore werkt anders: 100 is het snelste uiteinde en 0 het langzaamste uiteinde van het gemeten veld. Een veldscore van 75 betekent niet dat 75% van alle rijders is verslagen.','For comparison scores, 50 means roughly level with suitable other drivers. The metronome field score is different: 100 is the fastest end and 0 the slowest end of the measured field. A field score of 75 does not mean 75% of all drivers were beaten.')+
        '<details>'+bilingual('summary','Technisch: vaste scores','Technical: fixed scores')+
        p('Per schone ronde in vrije lucht is de veldscore 100 × (1 − (rang − 1) / (aantal gemeten rijders − 1)). We nemen de mediaan van die scores over de eigen loopbaan. Bij vijf gemeten rijders krijgen rangen 1 t/m 5 de waarden 100, 75, 50, 25 en 0. Het is een herschaalde rang, geen empirisch percentiel. Iedere bruikbare ronde telt mee.','For each clean clear-air lap, field score is 100 × (1 − (rank − 1) / (number of measured drivers − 1)). We take the median of those scores across the own career. With five measured drivers, ranks 1 to 5 score 100, 75, 50, 25 and 0. It is a rescaled rank, not an empirical percentile. Every usable lap counts.')+
        p('De vaste pitwaarde per race is de mediaan van de racemedianen, bij evenveel stops, afgeronde stopprogramma’s en zonder geregistreerde SC/VSC. De cycluswaarde gebruikt geaccepteerde kandidaatcycli. Een race kan meerdere cycli hebben: de noemers en betekenissen zijn dus verschillend. Beide waarden en de ongeronde pitcurve blijven apart bewaard.','The fixed pit value per race is the median of race medians with equal stop counts, completed pit programmes and no recorded SC/VSC. The cycle value uses accepted candidate cycles. A race can contain several cycles, so the denominators and meanings differ. Both values and the unrounded pit curve are retained separately.')+'</details>')
    section('pca','Hoe lees je de profielkaart?','How to read the profile map',
        p('Elke rijder krijgt één stip voor zijn hele loopbaan. De kaart probeert overeenkomsten tussen de gekozen kenmerken samen te vatten. Dichtbij betekent overeenkomst in die samenvatting. Hoger of verder naar rechts betekent niet beter. Niet alle verschillen passen in een kaart met twee assen.','Each driver gets one dot for their entire career. The map tries to summarize similarities in the chosen traits. Nearby means similar in that summary. Higher or farther right does not mean better. Not every difference fits on a map with two axes.')+
        p('Andere rijders selecteren geeft alleen kleur en namen. Andere kenmerken kiezen kan de hele kaart veranderen. Een rijder zonder voldoende gegevens blijft apart zichtbaar; we verzinnen geen ontbrekende getallen.','Selecting other drivers only adds colours and names. Choosing different traits can change the entire map. A driver without enough data remains visible separately; missing numbers are not invented.')+
        '<details>'+bilingual('summary','Technisch: PCA en netwerkmodel','Technical: PCA and network model')+
        p('De PCA gebruikt complete loopbaanprofielen. Standaard zijn dat gemiddelde relatieve gridpositie, gemiddelde relatieve raceklassering, zeges per bekende uitslag en rijdende finishes per bekende finishstatus. Een relatieve positie is (positie − 1) / (veldgrootte − 1). Ieder kenmerk wordt gecentreerd en gedeeld door zijn standaardafwijking; iedere coureur telt eenmaal. De eerste twee hoofdcomponenten worden getoond. De percentages bij de assen zijn aandelen van de variatie in deze gegevens, geen percentages rijvaardigheid.','PCA uses complete career profiles. Defaults are mean relative grid position, mean relative race classification, wins per known result and running finishes per known finish status. Relative position is (position − 1) / (field size − 1). Each feature is centred and divided by its standard deviation; each driver counts once. The first two principal components are shown. Axis percentages are shares of variation in these data, not percentages of driver skill.')+
        p('Het netwerkmodel gebruikt het laatste gemeenschappelijke kwalificatiesegment van teamgenoten en het verschil 100 × ln(tijd A / tijd B). Dat is een logaritmisch tempoverschil, niet exact het gewone procentuele tijdsverschil. Losse netwerkdelen zijn niet onderling gerangschikt. De modeltoets heeft nog geen algemene, tijdperkonafhankelijke kwaliteitsranglijst opgeleverd.','The network model uses teammates’ last shared qualifying segment and the difference 100 × ln(time A / time B). This is a logarithmic pace difference, not exactly an ordinary percentage time gap. Disconnected network components are not ranked against one another. Model testing has not produced a general era-independent skill ranking.')+'</details>')
    section('races','Positiewinst, inhalen en uitval','Positions gained, overtakes and retirements',
        p('Een plaats winnen is niet altijd een inhaalactie. Ook pitstops, uitval, straffen of het weer inhalen van een achterblijver kunnen de volgorde veranderen. Daarom houden de grafieken deze soorten gebeurtenissen uit elkaar. Bij oude races is soms alleen de positie aan het einde van iedere ronde bekend.','Gaining a place is not always an overtake. Pit stops, retirements, penalties or unlapping can also change the order. The charts therefore distinguish these event types. Older races sometimes provide only positions at each lap’s end.')+
        p('Een circuitmarker geeft de best onderbouwde beschikbare locatie weer. Die kan een zone zijn. Zonder betrouwbare locatie plaatsen we geen exact inhaalpunt. Een uitvalreden of botsing bewijst ook niet wie schuld had: daarvoor bekijken we het bijbehorende besluit.','A track marker shows the best-supported available location. It may be a zone. Without reliable location data, we do not place an exact overtaking point. A retirement reason or collision also does not prove fault: that requires reviewing the relevant ruling.'))
    page='''<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Begrijp de Formule 1-grafieken: voorbeelden, definities en berekeningen."><title>Uitleg bij de grafieken · Overtake It Away</title><link rel="stylesheet" href="assets/homepage.css"><style>body{margin:0;padding:20px;background:#0e131d;color:#f3f6fb;font:15px/1.65 system-ui,sans-serif}.help-shell{max-width:1200px;margin:auto}.help-card{background:#111824;border:1px solid #344053;border-top:3px solid #b45cff;border-radius:10px;padding:22px;margin:20px 0;scroll-margin-top:20px}.help-card h2{margin:0 0 14px;font-size:23px}.help-card p{max-width:88ch}.help-card details{border-top:1px solid #344053;margin-top:20px;padding-top:15px}.help-card summary{cursor:pointer;color:#d9b3ff;font-weight:750}.help-card a,.help-nav a{color:#51d6dd}.help-nav{display:flex;flex-wrap:wrap;gap:10px 20px}@media(max-width:600px){body{padding:12px}.help-card{padding:16px}}</style></head><body class="home-page"><div class="help-shell"><div class="race-hero">'''+branding('assets/f1-banner-v3.png',seasons_url='races.html')+'</div>'+bilingual('h1','Pitwall Briefing · begrijp de cijfers','Pitwall Briefing · understand the figures')+p('Wat laat de grafiek zien, hoe lees je haar en wat kun je er niet uit afleiden? De gewone uitleg staat voorop. Formules en rekenkeuzes kun je apart openklappen.','What does a chart show, how do you read it and what can you not infer from it? Plain explanations come first. Formulas and calculation choices can be expanded separately.')+'<nav class="help-nav">'+''.join(f'<a href="#{id}">{bilingual("span",nl,en)}</a>' for id,nl,en in [('lezen','Grafieken lezen','Reading charts'),('midden','Typische waarden','Typical values'),('onzekerheid','Onzekerheid','Uncertainty'),('coureurs','Coureurs','Drivers'),('goat','Vergelijken','Comparisons'),('pca','Profielkaart','Profile map'),('races','Racegebeurtenissen','Race events')])+'</nav><main>'+''.join(sections)+'</main></div><script defer src="assets/homepage.js"></script></body></html>'
    return with_navigation(page,'assets/')


def build(root):
    root=Path(root)
    text=with_hero_flag(render(),root/'index.html',root)
    (root/'uitleg.html').write_text(text)
    return root/'uitleg.html'
